#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct Rgba(pub u8, pub u8, pub u8, pub u8);

/// Final appearance of one span. Everything resolved; the renderer does no lookups.
#[derive(Copy, Clone, PartialEq, Eq, Debug, Default)]
pub struct Style {
    pub fg: Option<Rgba>, pub bg: Option<Rgba>, pub selected_fg: Option<Rgba>, pub selected_bg: Option<Rgba>,
    pub bold: bool, pub italic: bool, pub underline: bool, pub strikeout: bool,
}

/// The `editor-colors` block of a theme file, same keys as upstream Theme::EditorColorRole.
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)]
pub enum EditorColor { BackgroundColor, TextSelection, CurrentLine, SearchHighlight, ReplaceHighlight, BracketMatching, TabMarker, SpellChecking, IndentationLine, IconBorder, CodeFolding, LineNumbers, CurrentLineNumber, WordWrapMarker, ModifiedLines, SavedLines, Separator, MarkBookmark, MarkBreakpointActive, MarkBreakpointReached, MarkBreakpointDisabled, MarkExecution, MarkWarning, MarkError, TemplateBackground, TemplatePlaceholder, TemplateFocusedPlaceholder, TemplateReadOnlyPlaceholder }

pub struct Theme {
    pub name: String, pub revision: u32, pub license: String,
    text_styles: [Style; 31],                                          // indexed by DefaultStyle as usize
    editor_colors: std::collections::HashMap<EditorColor, Rgba>,
    custom_styles: std::collections::HashMap<(String, String), Style>, // (definition name, format name)
}
impl Theme {
    pub fn from_json(json: &str) -> Result<Theme, ThemeError>;
    pub fn text_style(&self, s: DefaultStyle) -> Style;
    pub fn editor_color(&self, c: EditorColor) -> Option<Rgba>;
    /// custom_styles[(def, format)] overrides Format fields override text_style(format.style).
    pub fn resolve(&self, definition: &str, format: &Format) -> Style;
}

#[derive(Debug)]
pub enum ThemeError { Json(serde_json::Error), UnknownStyle(String), BadColor(String) }
